package dev.livingrealms.minecraft.client;
import com.mojang.blaze3d.vertex.*;import dev.livingrealms.LivingRealms;import dev.livingrealms.minecraft.entity.MilitaryUnitEntity;import dev.livingrealms.sim.military.MilitaryUnitClass;import net.minecraft.client.model.EntityModel;import net.minecraft.client.model.geom.*;import net.minecraft.client.model.geom.builders.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.util.Mth;
public final class MilitaryUnitModel extends EntityModel<MilitaryUnitEntity>{public static final ModelLayerLocation LAYER=new ModelLayerLocation(ResourceLocation.fromNamespaceAndPath(LivingRealms.MOD_ID,"military_unit"),"main");private final ModelPart body,head,larm,rarm,lleg,rleg,vehicle;public MilitaryUnitModel(ModelPart r){body=r.getChild("body");head=r.getChild("head");larm=r.getChild("larm");rarm=r.getChild("rarm");lleg=r.getChild("lleg");rleg=r.getChild("rleg");vehicle=r.getChild("vehicle");}public static LayerDefinition createBodyLayer(){MeshDefinition m=new MeshDefinition();PartDefinition r=m.getRoot();r.addOrReplaceChild("head",CubeListBuilder.create().texOffs(0,0).addBox(-4,-8,-4,8,8,8),PartPose.offset(0,8,0));r.addOrReplaceChild("body",CubeListBuilder.create().texOffs(16,16).addBox(-4,0,-2,8,12,4),PartPose.offset(0,8,0));r.addOrReplaceChild("larm",CubeListBuilder.create().texOffs(40,16).addBox(-2,0,-2,4,12,4),PartPose.offset(6,8,0));r.addOrReplaceChild("rarm",CubeListBuilder.create().texOffs(40,16).addBox(-2,0,-2,4,12,4),PartPose.offset(-6,8,0));r.addOrReplaceChild("lleg",CubeListBuilder.create().texOffs(0,16).addBox(-2,0,-2,4,12,4),PartPose.offset(2,20,0));r.addOrReplaceChild("rleg",CubeListBuilder.create().texOffs(0,16).addBox(-2,0,-2,4,12,4),PartPose.offset(-2,20,0));r.addOrReplaceChild("vehicle",CubeListBuilder.create().texOffs(0,36).addBox(-8,-6,-10,16,8,20).texOffs(0,0).addBox(-2,-9,-2,4,4,10),PartPose.offset(0,20,0));return LayerDefinition.create(m,64,64);}public void setupAnim(MilitaryUnitEntity e,float s,float a,float age,float yaw,float pitch){boolean v=e.unitClass()==MilitaryUnitClass.ARMOR||e.unitClass()==MilitaryUnitClass.ARTILLERY;vehicle.visible=v;head.visible=!v;body.visible=!v;larm.visible=!v;rarm.visible=!v;lleg.visible=!v;rleg.visible=!v;if(!v){head.yRot=yaw*((float)Math.PI/180);head.xRot=pitch*((float)Math.PI/180);rarm.xRot=Mth.cos(s*.6662F+(float)Math.PI)*a;larm.xRot=Mth.cos(s*.6662F)*a;rleg.xRot=Mth.cos(s*.6662F)*1.4F*a;lleg.xRot=Mth.cos(s*.6662F+(float)Math.PI)*1.4F*a;}}public void renderToBuffer(PoseStack p,VertexConsumer b,int l,int o,int c){head.render(p,b,l,o,c);body.render(p,b,l,o,c);larm.render(p,b,l,o,c);rarm.render(p,b,l,o,c);lleg.render(p,b,l,o,c);rleg.render(p,b,l,o,c);vehicle.render(p,b,l,o,c);}}
